15	// ── Shared state ──────────────────────────────────────────────────────────────
16	
17	/// App-wide OAuth state registered via `.manage()` in lib.rs.
18	///
19	/// Both fields are Option-wrapped so the state is cleanly empty before any
20	/// OAuth flow starts and after a flow completes.
21	pub struct AppState {
22	    /// The pending OAuth flow waiting for the deep-link callback.
23	    /// Set by `start_oauth_flow` before opening Safari; cleared by `handle_deep_link`.
24	    pub pending_auth: Mutex<Option<PendingOAuthFlow>>,
25	    /// The active authenticated session after a successful token exchange.
26	    /// Set by `start_oauth_flow` on success; read by `OAuthClient` for every request.
27	    pub oauth_session: Mutex<Option<OAuthSession>>,
28	    /// Runtime relay client. Populated from Keychain on startup or by
29	    /// `save_relay_url` on first launch. Falls back to the compile-time default if unset.
30	    relay_client: OnceLock<crate::http::RelayClient>,
31	    /// PDS client for discovery and XRPC operations against arbitrary PDS endpoints.
32	    /// Stateless and cheap to construct; available to Phase 4 Tauri commands.
33	    pds_client: crate::pds_client::PdsClient,
34	    /// Claim flow state persisted across multi-step claim commands.
35	    /// Set by `resolve_identity`; used by subsequent `start_pds_auth`,
36	    /// `request_claim_verification`, `sign_and_verify_claim`, `submit_claim`.
37	    /// Uses tokio::sync::Mutex because claim commands hold the lock across .await points.
38	    pub claim_state: tokio::sync::Mutex<Option<crate::claim::ClaimState>>,
39	    /// Recovery override state persisted between build and submit.
40	    /// Set by `build_recovery_override` after signing; used by `submit_recovery_override`.
41	    /// Uses tokio::sync::Mutex because recovery commands hold the lock across .await points.
42	    pub recovery_state: tokio::sync::Mutex<Option<crate::recovery::RecoveryState>>,
43	}
