45	impl AppState {
46	    pub fn new() -> Self {
47	        Self {
48	            pending_auth: Mutex::new(None),
49	            oauth_session: Mutex::new(None),
50	            relay_client: OnceLock::new(),
51	            pds_client: crate::pds_client::PdsClient::new(),
52	            claim_state: tokio::sync::Mutex::new(None),
53	            recovery_state: tokio::sync::Mutex::new(None),
54	        }
55	    }
56	
57	    /// Returns the configured relay client, or initializes with the compile-time
58	    /// default URL if none has been set yet.
59	    pub fn relay_client(&self) -> &crate::http::RelayClient {
60	        self.relay_client.get_or_init(crate::http::RelayClient::new)
61	    }
62	
63	    /// Set the relay client from a runtime URL. Silently ignored if already set
64	    /// (OnceLock::set semantics — this is only called once on first launch).
65	    pub fn set_relay_client(&self, url: String) {
66	        if self
67	            .relay_client
68	            .set(crate::http::RelayClient::new_with_url(url.clone()))
