87	// ── OAuth error ───────────────────────────────────────────────────────────────
88	
89	/// Error type for all OAuth-related operations.
90	///
91	/// Variants serialize as `{ "code": "SCREAMING_SNAKE_CASE" }` to match the
92	/// existing error pattern (`CreateAccountError`, `DeviceKeyError`, etc.).
93	#[derive(Debug, thiserror::Error, serde::Serialize)]
94	#[serde(rename_all = "SCREAMING_SNAKE_CASE", tag = "code")]
95	pub enum OAuthError {
96	    #[error("DPoP keypair generation failed")]
97	    DpopKeyGenFailed,
98	    #[error("DPoP keypair is invalid")]
99	    DpopKeyInvalid,
100	    #[error("DPoP proof construction failed")]
101	    DpopProofFailed,
102	    #[error("Keychain error")]
103	    KeychainError,
104	    #[error("State mismatch in OAuth callback")]
105	    StateMismatch,
106	    #[error("OAuth callback abandoned")]
107	    CallbackAbandoned,
108	    #[error("PAR request failed")]
109	    ParFailed,
110	    #[error("Token exchange failed")]
111	    TokenExchangeFailed,
112	    #[error("Token refresh failed")]
113	    TokenRefreshFailed,
114	    #[error("Refresh token has been revoked or is invalid")]
115	    InvalidGrant,
116	    #[error("Not authenticated")]
117	    NotAuthenticated,
118	}
119	
120	// ── DPoP keypair ─────────────────────────────────────────────────────────────
121	
122	/// A P-256 keypair used to produce DPoP proofs.
123	///
124	/// The private key scalar (32 bytes) is persisted in the iOS Keychain under
125	/// `"oauth-dpop-key-priv"`. The same key is used for all DPoP proofs across
126	/// app sessions — it is never rotated by this implementation.
127	pub struct DPoPKeypair {
128	    signing_key: SigningKey,
129	}
130	
131	impl DPoPKeypair {
132	    /// Load the DPoP keypair from Keychain, or generate and persist a new one.
133	    pub fn get_or_create() -> Result<Self, OAuthError> {
134	        if let Some(private_bytes) = crate::keychain::load_dpop_key() {
135	            // private_bytes is Zeroizing<[u8; 32]>, which derefs to [u8; 32].
136	            // Dereference to get &[u8; 32], which coerces to &[u8] for from_slice.
137	            let signing_key =
138	                SigningKey::from_slice(&*private_bytes).map_err(|_| OAuthError::DpopKeyInvalid)?;
139	            return Ok(Self { signing_key });
140	        }
141	
142	        // Generate a new P-256 keypair via the shared crypto crate.
143	        let keypair = crypto::generate_p256_keypair().map_err(|_| OAuthError::DpopKeyGenFailed)?;
144	        // `private_key_bytes` is `Zeroizing<[u8; 32]>`, which derefs directly to `[u8; 32]`.
145	        let private_bytes: [u8; 32] = *keypair.private_key_bytes;
146	
147	        crate::keychain::store_dpop_key(&private_bytes).map_err(|_| OAuthError::KeychainError)?;
148	
149	        let signing_key =
150	            SigningKey::from_slice(&private_bytes).map_err(|_| OAuthError::DpopKeyInvalid)?;
151	        Ok(Self { signing_key })
152	    }
153	
154	    /// Build the public JWK for this keypair (EC, P-256, kty/crv/x/y only — no private fields).
155	    ///
156	    /// The relay's validator expects exactly: `{"kty":"EC","crv":"P-256","x":"<b64url>","y":"<b64url>"}`.
157	    pub fn public_jwk(&self) -> serde_json::Value {
158	        let verifying_key = self.signing_key.verifying_key();
159	        let point = verifying_key.to_encoded_point(false); // false = uncompressed: 04 || x || y
160	        let x = URL_SAFE_NO_PAD.encode(point.x().expect("P-256 uncompressed point has x"));
161	        let y = URL_SAFE_NO_PAD.encode(point.y().expect("P-256 uncompressed point has y"));
162	        serde_json::json!({
163	            "kty": "EC",
164	            "crv": "P-256",
165	            "x": x,
166	            "y": y,
167	        })
168	    }
169	
170	    /// Compute the RFC 7638 JWK thumbprint: `base64url(SHA-256(canonical_jwk_json))`.
171	    ///
172	    /// The canonical JSON uses lexicographically-sorted keys (crv, kty, x, y) per RFC 7638 §3.2.
173	    /// This matches the relay's `jwk_thumbprint()` function in `crates/relay/src/auth/dpop.rs`.
174	    pub fn public_jwk_thumbprint(&self) -> String {
175	        let jwk = self.public_jwk();
176	        // Canonical member set per RFC 7638 §3.2 — lexicographic order for EC keys.
177	        // serde_json internally represents JSON objects as BTreeMap, which serializes
178	        // keys in lexicographic order. This is what RFC 7638 §3.2 requires for the
179	        // canonical JSON. The key ordering here (crv < kty < x < y) is lexicographic.
180	        let canonical = serde_json::json!({
181	            "crv": jwk["crv"],
182	            "kty": jwk["kty"],
183	            "x": jwk["x"],
184	            "y": jwk["y"],
185	        });
186	        let canonical_json = serde_json::to_string(&canonical)
187	            .expect("canonical JWK serialization is infallible for known types");
188	        let hash = Sha256::digest(canonical_json.as_bytes());
189	        URL_SAFE_NO_PAD.encode(hash)
190	    }
191	
192	    /// Build a DPoP proof JWT for the given HTTP method, URL, and optional claims.
193	    ///
194	    /// - `htm`: HTTP method in uppercase, e.g. `"POST"` or `"GET"`
195	    /// - `htu`: Full target URL without query string, e.g. `"https://relay.ezpds.com/oauth/token"`
196	    /// - `nonce`: Server-issued nonce from a prior `use_dpop_nonce` 400 response (if any)
197	    /// - `ath`: `base64url(SHA-256(access_token_ascii))` — required for resource requests; None for token requests
198	    ///
199	    /// Proof format: `base64url(header_json)`.`base64url(claims_json)`.`base64url(sig)`
200	    /// where sig is the raw 64-byte R||S P-256 ECDSA signature of the signing input.
201	    pub fn make_proof(
202	        &self,
203	        htm: &str,
204	        htu: &str,
205	        nonce: Option<&str>,
206	        ath: Option<&str>,
207	    ) -> Result<String, OAuthError> {
208	        let jwk = self.public_jwk();
209	
210	        // Header JSON.
211	        let header = serde_json::json!({
212	            "typ": "dpop+jwt",
213	            "alg": "ES256",
214	            "jwk": jwk,
215	        });
216	        let header_b64 = URL_SAFE_NO_PAD
217	            .encode(serde_json::to_vec(&header).map_err(|_| OAuthError::DpopProofFailed)?);
218	
219	        // Claims JSON.
220	        let iat = SystemTime::now()
221	            .duration_since(UNIX_EPOCH)
222	            .map_err(|_| OAuthError::DpopProofFailed)?
223	            .as_secs() as i64;
224	
225	        let mut claims = serde_json::json!({
226	            "jti": Uuid::new_v4().to_string(),
227	            "htm": htm,
228	            "htu": htu,
229	            "iat": iat,
230	        });
231	
232	        if let Some(n) = nonce {
233	            claims["nonce"] = serde_json::Value::String(n.to_string());
234	        }
235	        if let Some(a) = ath {
236	            claims["ath"] = serde_json::Value::String(a.to_string());
237	        }
238	
239	        let claims_b64 = URL_SAFE_NO_PAD
240	            .encode(serde_json::to_vec(&claims).map_err(|_| OAuthError::DpopProofFailed)?);
241	
242	        // Sign `header_b64.claims_b64` bytes with P-256/SHA-256.
243	        let signing_input = format!("{header_b64}.{claims_b64}");
244	        let signature: Signature = self.signing_key.sign(signing_input.as_bytes());
245	        // Normalize to low-S (consistent with the rest of the codebase, even though
246	        // the relay's DPoP validator does not require it — low-S is harmless and keeps
247	        // key usage consistent with ATProto expectations).
248	        let signature = signature.normalize_s().unwrap_or(signature);
249	        let sig_b64 = URL_SAFE_NO_PAD.encode(signature.to_bytes().as_slice());
250	
251	        Ok(format!("{signing_input}.{sig_b64}"))
252	    }
253	
254	    /// Compute `base64url(SHA-256(access_token))` — the `ath` claim for resource requests.
255	    pub fn compute_ath(access_token: &str) -> String {
256	        let hash = Sha256::digest(access_token.as_bytes());
257	        URL_SAFE_NO_PAD.encode(hash)
258	    }
259	}
260	
261	// ── PKCE utilities ────────────────────────────────────────────────────────────
262	
263	pub mod pkce {
264	    use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine};
265	    use rand_core::{OsRng, RngCore};
266	    use sha2::{Digest, Sha256};
267	
268	    /// Generate a PKCE code_verifier and code_challenge pair.
269	    ///
270	    /// - `verifier`: 32 OS-random bytes base64url-encoded (43 chars, all unreserved per RFC 7636 §4.1)
271	    /// - `challenge`: `base64url(SHA-256(verifier))` (S256 method per RFC 7636 §4.2)
272	    ///
273	    /// Returns `(verifier, challenge)`.
274	    pub fn generate() -> (String, String) {
275	        let mut bytes = [0u8; 32];
276	        OsRng.fill_bytes(&mut bytes);
277	        let verifier = URL_SAFE_NO_PAD.encode(bytes);
278	        let challenge = URL_SAFE_NO_PAD.encode(Sha256::digest(verifier.as_bytes()));
279	        (verifier, challenge)
280	    }
281	}
282	
283	/// Generate a CSRF state parameter: 16 OS-random bytes base64url-encoded (22 chars).
284	pub fn generate_state_param() -> String {
285	    use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine};
286	    let mut bytes = [0u8; 16];
287	    OsRng.fill_bytes(&mut bytes);
288	    URL_SAFE_NO_PAD.encode(bytes)
289	}
290	
291	// ── Pending flow ──────────────────────────────────────────────────────────────
292	
293	/// State parked inside `AppState.pending_auth` while `start_oauth_flow` waits
294	/// for the deep-link callback.
295	pub struct PendingOAuthFlow {
296	    /// Channel to deliver the callback result back to `start_oauth_flow`.
297	    ///
298	    /// Sends `Ok(CallbackParams)` on success or `Err(OAuthError::StateMismatch)` on
299	    /// CSRF mismatch, so the command can distinguish a mismatch from a dropped channel.
300	    pub tx: tokio::sync::oneshot::Sender<Result<CallbackParams, OAuthError>>,
301	    /// PKCE code_verifier to include in the token exchange.
302	    pub pkce_verifier: String,
303	    /// CSRF state parameter — validated against the callback's state param.
304	    pub csrf_state: String,
305	}
306	
307	// ── OAuth session ─────────────────────────────────────────────────────────────
308	
309	/// Active OAuth session stored in AppState after successful token exchange.
310	#[derive(Clone)]
311	pub struct OAuthSession {
312	    pub access_token: String,
313	    pub refresh_token: String,
314	    /// Unix timestamp (seconds) when the access token expires.
315	    pub expires_at: u64,
316	    /// The most recent DPoP nonce issued by the server.
317	    /// Starts as None; updated whenever the server sends a DPoP-Nonce header.
318	    pub dpop_nonce: Option<String>,
319	}
320	
321	// ── Callback params ───────────────────────────────────────────────────────────
322	
323	/// Parameters extracted from the OAuth deep-link callback URL.
324	pub struct CallbackParams {
325	    pub code: String,
326	    pub state: String,
327	}
328	
329	// ── Deep-link handler ─────────────────────────────────────────────────────────
330	
331	/// Process URLs received from the deep-link plugin's `on_open_url` event.
332	///
333	/// Filters for the OAuth callback path, extracts `code` and `state`, validates the
334	/// CSRF state against the pending flow, and sends `CallbackParams` on the oneshot channel.
335	///
336	/// Called from the `on_open_url` closure in lib.rs (sync context — no async).
337	/// A second callback (replay) is silently ignored because `pending_auth.take()` clears
338	/// the slot on first receipt.
339	pub fn handle_deep_link(urls: Vec<url::Url>, app_state: &AppState) {
340	    for url in &urls {
341	        let scheme = url.scheme();
342	        let path = url.path();
343	
344	        if scheme == "dev.malpercio.identitywallet" && path == "/oauth/callback" {
345	            tracing::info!(url = %url, "OAuth deep-link callback received");
346	
347	            // Take the pending flow — clears the slot so replays are silently ignored.
348	            let pending = app_state.pending_auth.lock().unwrap().take();
349	            let Some(flow) = pending else {
350	                tracing::warn!(
351	                    "OAuth callback received but no flow is pending; ignoring (replay?)"
352	                );
353	                return;
354	            };
355	
356	            // Extract code and state from query parameters.
357	            let mut code_opt: Option<String> = None;
358	            let mut state_opt: Option<String> = None;
359	            for (key, value) in url.query_pairs() {
360	                match key.as_ref() {
361	                    "code" => code_opt = Some(value.into_owned()),
362	                    "state" => state_opt = Some(value.into_owned()),
363	                    _ => {}
364	                }
365	            }
366	
367	            let (Some(code), Some(callback_state)) = (code_opt, state_opt) else {
368	                tracing::error!("OAuth callback URL missing code or state parameters");
369	                // Send an explicit error instead of silently dropping the sender.
370	                let _ = flow.tx.send(Err(OAuthError::CallbackAbandoned));
371	                return;
372	            };
373	
374	            // Validate CSRF state — must match before sending on the channel.
375	            if callback_state != flow.csrf_state {
376	                tracing::error!(
377	                    expected = %flow.csrf_state,
378	                    received = %callback_state,
379	                    "CSRF state mismatch in OAuth callback; aborting flow"
380	                );
381	                // Send the error explicitly so start_oauth_flow returns StateMismatch,
382	                // not CallbackAbandoned (which would occur if we just dropped tx).
383	                let _ = flow.tx.send(Err(OAuthError::StateMismatch));
384	                return;
385	            }
386	
387	            let _ = flow.tx.send(Ok(CallbackParams {
388	                code,
389	                state: callback_state,
390	            }));
391	            return;
392	        }
393	
394	        tracing::debug!(url = %url, "ignoring non-OAuth deep-link");
395	    }
396	}
397	
398	// ── Tauri command ─────────────────────────────────────────────────────────────
399	
400	/// Drive the full OAuth 2.0 PKCE + DPoP authorization round-trip.
401	///
402	/// Called from the SvelteKit frontend via `invoke('start_oauth_flow')`.
403	/// Parks on a Tokio oneshot channel until `handle_deep_link` delivers
404	/// the authorization code from the system browser redirect.
405	///
406	/// # Flow
407	/// 1. Generate PKCE verifier/challenge and CSRF state parameter
408	/// 2. Get-or-create DPoP keypair; build PAR DPoP proof
409	/// 3. POST /oauth/par → receive request_uri
410	/// 4. Open system browser to /oauth/authorize?client_id=...&request_uri=...
411	/// 5. Park on oneshot receiver; handle_deep_link will send the code+state
412	/// 6. Validate CSRF state matches
413	/// 7. POST /oauth/token (authorization_code grant + PKCE verifier + DPoP proof)
414	///    → on use_dpop_nonce 400: retry with server-issued nonce
415	/// 8. Store access_token + refresh_token in Keychain
416	/// 9. Populate AppState.oauth_session
417	#[tauri::command]
418	pub async fn start_oauth_flow(
419	    app: tauri::AppHandle,
420	    state: tauri::State<'_, AppState>,
421	    login_hint: Option<String>,
422	) -> Result<(), OAuthError> {
423	    // OpenerExt adds the `.opener()` method to AppHandle.
424	    use tauri_plugin_opener::OpenerExt;
425	
426	    let relay = state.relay_client();
427	
428	    // 1. Generate PKCE and CSRF state.
429	    let (pkce_verifier, pkce_challenge) = pkce::generate();
430	    let csrf_state = generate_state_param();
431	
432	    // 2. Get-or-create DPoP keypair.
433	    let dpop = DPoPKeypair::get_or_create()?;
434	    let dpop_jkt = dpop.public_jwk_thumbprint();
435	
436	    let par_htu = format!("{}/oauth/par", state.relay_client().base_url_str());
437	    let par_proof = dpop.make_proof("POST", &par_htu, None, None)?;
438	
439	    // 3. PAR call.
440	    let par_resp = relay
441	        .par(
442	            &pkce_challenge,
443	            &csrf_state,
444	            &par_proof,
445	            &dpop_jkt,
446	            login_hint.as_deref(),
447	        )
448	        .await?;
449	
450	    // 4. Set up the oneshot channel and park pending_auth.
451	    let (tx, rx) = tokio::sync::oneshot::channel::<Result<CallbackParams, OAuthError>>();
452	    {
453	        let mut pending = state.pending_auth.lock().unwrap();
454	        *pending = Some(PendingOAuthFlow {
455	            tx,
456	            pkce_verifier: pkce_verifier.clone(),
457	            csrf_state: csrf_state.clone(),
458	        });
459	    } // Mutex guard dropped here — not held across .await.
460	
461	    // 5. Open Safari to the authorization endpoint.
462	    let auth_url = {
463	        let base = state.relay_client().base_url_str();
464	        let request_uri_encoded =
465	            url::form_urlencoded::byte_serialize(par_resp.request_uri.as_bytes())
466	                .collect::<String>();
467	        let mut u = format!(
468	            "{base}/oauth/authorize?client_id=dev.malpercio.identitywallet&request_uri={request_uri_encoded}"
469	        );
470	        if let Some(hint) = &login_hint {
471	            let hint_encoded =
472	                url::form_urlencoded::byte_serialize(hint.as_bytes()).collect::<String>();
473	            u.push_str(&format!("&login_hint={hint_encoded}"));
474	        }
475	        u
476	    };
477	
478	    app.opener()
479	        .open_url(&auth_url, None::<&str>)
480	        .map_err(|e| {
481	            tracing::error!(error = %e, "failed to open system browser for OAuth");
482	            OAuthError::ParFailed
483	        })?;
484	
485	    // 6. Wait for the deep-link callback to deliver the authorization code.
486	    // The outer ? handles RecvError (channel dropped) → CallbackAbandoned.
487	    // The inner ? propagates OAuthError::StateMismatch if handle_deep_link detected a CSRF mismatch.
488	    let callback = rx.await.map_err(|_| OAuthError::CallbackAbandoned)??;
489	
490	    // 7. Token exchange.
491	    let token_htu = format!("{}/oauth/token", state.relay_client().base_url_str());
492	    let (token_resp, initial_nonce) =
493	        exchange_code_with_retry(relay, &dpop, &callback.code, &pkce_verifier, &token_htu).await?;
494	
495	    // 8. Store tokens in Keychain.
496	    crate::keychain::store_oauth_tokens(&token_resp.access_token, &token_resp.refresh_token)
497	        .map_err(|_| OAuthError::KeychainError)?;
498	
499	    // 9. Update AppState.
500	    // Seed dpop_nonce from the token response to avoid a guaranteed use_dpop_nonce retry
501	    // on the first OAuthClient request immediately after login.
502	    let expires_at = std::time::SystemTime::now()
503	        .duration_since(std::time::UNIX_EPOCH)
504	        .map_err(|_| OAuthError::TokenExchangeFailed)?
505	        .as_secs()
506	        + token_resp.expires_in;
507	
508	    let mut session = state.oauth_session.lock().unwrap();
509	    *session = Some(OAuthSession {
510	        access_token: token_resp.access_token,
511	        refresh_token: token_resp.refresh_token,
512	        expires_at,
513	        dpop_nonce: initial_nonce,
514	    });
515	
516	    tracing::info!("OAuth flow complete; session stored");
517	    Ok(())
518	}
