399	      <Button onclick={() => { authError = null; goTo('authenticating'); }}>Try again</Button>
400	      <Button variant="secondary" onclick={() => { authError = null; goTo('welcome'); }}>Start over</Button>
401	    </OnboardingShell>
402	  {/if}
403	</div>
